Here's a complete example with both `DataRow` and `DynamicData` approaches:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace PriceCalculator.Tests;

[TestClass]
public class PriceCalculatorTests
{
    private Calculator.PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new Calculator.PriceCalculator();

    // --- DataRow: inline constant values ---

    [TestMethod]
    [DataRow(1, 10.00, 10.00)]
    [DataRow(5, 3.50, 17.50)]
    [DataRow(0, 99.99, 0.00)]
    [DataRow(100, 0.01, 1.00)]
    public void CalculateTotal_ReturnsExpected(int quantity, double price, double expected)
    {
        var result = _calculator.CalculateTotal(quantity, (decimal)price);
        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(100.00, 0.10, 90.00)]   // 10% off
    [DataRow(100.00, 0.00, 100.00)]  // no discount
    [DataRow(49.99, 0.50, 25.00)]    // 50% off (rounded)
    [DataRow(200.00, 1.00, 0.00)]    // 100% off
    public void ApplyDiscount_ReturnsExpected(double total, double discount, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)total, (decimal)discount);
        Assert.AreEqual((decimal)expected, Math.Round(result, 2));
    }

    // --- DynamicData: complex/non-constant scenarios ---

    [TestMethod]
    [DynamicData(nameof(BulkOrderCases), DynamicDataSourceType.Method)]
    public void CalculateTotal_BulkOrders_ReturnsExpected(
        int quantity, decimal price, decimal expected, string scenario)
    {
        var result = _calculator.CalculateTotal(quantity, price);
        Assert.AreEqual(expected, result, $"Failed for: {scenario}");
    }

    private static IEnumerable<object[]> BulkOrderCases()
    {
        yield return new object[] { 1000, 5.99m, 5990.00m, "large quantity standard price" };
        yield return new object[] { 1, 9999.99m, 9999.99m, "single expensive item" };
        yield return new object[] { 250, 0.10m, 25.00m, "many cheap items" };
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_InvalidInput_ThrowsArgumentException(
        decimal total, decimal discount)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(total, discount));
    }

    private static IEnumerable<object[]> InvalidDiscountCases()
    {
        yield return new object[] { 100m, -0.1m };   // negative discount
        yield return new object[] { 100m, 1.5m };    // over 100%
        yield return new object[] { -50m, 0.1m };    // negative total
    }
}
```

**Key best practices shown:**

| Practice | Detail |
|----------|--------|
| `DataRow` | Best for simple, inline constant values (note: `decimal` literals aren't allowed — use `double` and cast) |
| `DynamicData` | Best for `decimal`, complex objects, or computed test data |
| `DynamicDataSourceType.Method` | Preferred over `Property` for lazy evaluation via `yield return` |
| Descriptive scenario param | Adds context to failure messages |
| `TestInitialize` | Keeps setup DRY |
| Boundary values | Zero, 100%, max quantity, rounding |
| Negative tests | Validates input guards throw |

To use this, add the `Microsoft.NET.Test.Sdk` and `MSTest.TestFramework` / `MSTest.TestAdapter` NuGet packages (or the unified `MSTest` 3.x meta-package). Want me to scaffold a full `.csproj` and class implementation as well?
